import React, { useEffect, useState } from "react";
import axios from "axios";
import "./Dashboard.css";

function Dashboard() {
  const [transactions, setTransactions] = useState([]);
  const [title, setTitle] = useState("");
  const [amount, setAmount] = useState("");
  const [category, setCategory] = useState("");
  const [date, setDate] = useState("");
  const [notes, setNotes] = useState("");
  const [page, setPage] = useState(1);
  const [editId, setEditId] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterCategory, setFilterCategory] = useState("All");

  const token = localStorage.getItem("token");

  // ================= FETCH =================
  const fetchTransactions = async () => {
    const res = await axios.get(
      `http://localhost:5000/transactions?page=${page}`,
      {
        headers: { authorization: token },
      }
    );
    setTransactions(res.data);
  };

  useEffect(() => {
    fetchTransactions();
  }, [page]);

  // ================= ADD / UPDATE =================
  const addTransaction = async () => {
    if (!title || !amount || !category || !date) {
      alert("Please fill all required fields");
      return;
    }

    if (editId) {
      await axios.put(
        `http://localhost:5000/transactions/${editId}`,
        { title, amount, category, date, notes },
        { headers: { authorization: token } }
      );
      setEditId(null);
    } else {
      await axios.post(
        "http://localhost:5000/transactions",
        { title, amount, category, date, notes },
        { headers: { authorization: token } }
      );
    }

    setTitle("");
    setAmount("");
    setCategory("");
    setDate("");
    setNotes("");

    fetchTransactions();
  };

  // ================= DELETE =================
  const deleteTransaction = async (id) => {
    if (window.confirm("Are you sure you want to delete?")) {
      await axios.delete(`http://localhost:5000/transactions/${id}`, {
        headers: { authorization: token },
      });
      fetchTransactions();
    }
  };

  // ================= EDIT =================
  const handleEdit = (transaction) => {
    setEditId(transaction.id);
    setTitle(transaction.title);
    setAmount(transaction.amount);
    setCategory(transaction.category);
    setDate(transaction.date);
    setNotes(transaction.notes);
  };

  // ================= TOTAL =================
  const totalExpense = transactions.reduce(
    (acc, t) => acc + parseFloat(t.amount),
    0
  );

  // ================= CATEGORY BREAKDOWN =================
  const categoryTotals = {};
  transactions.forEach((t) => {
    if (!categoryTotals[t.category]) {
      categoryTotals[t.category] = 0;
    }
    categoryTotals[t.category] += parseFloat(t.amount);
  });

  // ================= SEARCH + FILTER =================
  const filteredTransactions = transactions.filter((t) => {
    const matchesSearch = t.title
      .toLowerCase()
      .includes(searchTerm.toLowerCase());

    const matchesCategory =
      filterCategory === "All" || t.category === filterCategory;

    return matchesSearch && matchesCategory;
  });

  const handleLogout = () => {
    localStorage.removeItem("token");
    window.location.href = "/";
  };

  return (
    <div className="dashboard-container">
      <div className="dashboard-header">
        <h2>Expense Dashboard</h2>
        <button className="logout-btn" onClick={handleLogout}>
          Logout
        </button>
      </div>

      <div className="summary-card">
        <h3>Total Expense: ₹ {totalExpense}</h3>
      </div>

      <div className="summary-card">
        <h3>Category Breakdown</h3>
        {Object.keys(categoryTotals).map((cat) => (
          <p key={cat}>
            {cat} : ₹ {categoryTotals[cat]}
          </p>
        ))}
      </div>

      <div className="form-section">
        <h3>{editId ? "Edit Transaction" : "Add Transaction"}</h3>

        <input
          placeholder="Title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
        />

        <input
          placeholder="Amount"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
        />

        <input
          placeholder="Category"
          value={category}
          onChange={(e) => setCategory(e.target.value)}
        />

        <input
          type="date"
          value={date}
          onChange={(e) => setDate(e.target.value)}
        />

        <input
          placeholder="Notes"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
        />

        <button className="add-btn" onClick={addTransaction}>
          {editId ? "Update" : "Add"}
        </button>
      </div>

      <h3>Transaction Explorer</h3>

      <input
        placeholder="Search by title"
        onChange={(e) => setSearchTerm(e.target.value)}
      />

      <select onChange={(e) => setFilterCategory(e.target.value)}>
        <option value="All">All</option>
        <option value="Food">Food</option>
        <option value="Rent">Rent</option>
        <option value="Transport">Transport</option>
        <option value="Shopping">Shopping</option>
      </select>

      {filteredTransactions.length === 0 && <p>No transactions found</p>}

      {filteredTransactions.map((t) => (
        <div key={t.id} className="transaction-card">
          <p>
            <strong>{t.title}</strong> - ₹{t.amount}
          </p>
          <p>Category: {t.category}</p>
          <p>Date: {t.date}</p>

          <button onClick={() => handleEdit(t)}>Edit</button>
          <button
            className="delete-btn"
            onClick={() => deleteTransaction(t.id)}
          >
            Delete
          </button>
        </div>
      ))}

      <button className="load-btn" onClick={() => setPage(page + 1)}>
        Load More
      </button>
    </div>
  );
}

export default Dashboard;
